// Research Brief generation and validation. Every citation [n]
// must resolve to sources[n - 1]; validation fails closed so the UI
// can never show invented references.
const {
  readSession,
} = require('./session-store.cjs')

const MAX_BRIEF_CHARS = 24000

// Source-derived text (titles, abstracts, even the user's own
// objective) may contain bracketed numbers like [99] or [2024] that
// are NOT citations. The validator cannot tell them from real ones,
// so they are rewritten to (n) wherever untrusted text is embedded.
// Only the [n] markers generated by the builders keep citation
// meaning. URLs are percent-encoded instead so links stay usable.
function sanitizeCitationLookalikes(text) {
  return String(text || '').replace(/\[(\d+)\]/g, '($1)')
}

function renderUrl(url) {
  return String(url || '').replace(/\[/g, '%5B').replace(/\]/g, '%5D').slice(0, 2000)
}

function citationIndexes(markdown) {
  const indexes = new Set()
  const pattern = /\[(\d+)\]/g
  let match = null

  while ((match = pattern.exec(String(markdown || ''))) !== null) {
    indexes.add(Number(match[1]))
  }

  return [...indexes]
}

function validateBrief(markdown, sources) {
  const errors = []
  const count = Array.isArray(sources) ? sources.length : 0

  if (typeof markdown !== 'string' || !markdown.trim()) {
    errors.push('Brief is empty.')
  }

  if (markdown && markdown.length > MAX_BRIEF_CHARS) {
    errors.push(`Brief exceeds ${MAX_BRIEF_CHARS} characters.`)
  }

  for (const index of citationIndexes(markdown)) {
    if (index < 1 || index > count) {
      errors.push(`Citation [${index}] has no matching source (1-${count}).`)
    }
  }

  // Sources cited must carry a retrievable URL.
  const cited = citationIndexes(markdown).filter((index) => index >= 1 && index <= count)

  for (const index of cited) {
    const source = sources[index - 1]

    if (!source || typeof source.url !== 'string' || !/^https?:\/\//i.test(source.url)) {
      errors.push(`Citation [${index}] points at a source without a valid URL.`)
    }
  }

  return { ok: errors.length === 0, errors }
}

function sourceLine(index, source) {
  const authors = Array.isArray(source.authors) && source.authors.length > 0
    ? ` — ${sanitizeCitationLookalikes(source.authors.slice(0, 4).join(', '))}`
    : ''
  const date = source.publishedAt ? ` (${String(source.publishedAt).slice(0, 10)})` : ''
  const venue = source.venue ? `, ${sanitizeCitationLookalikes(source.venue)}` : ''
  const kind = source.sourceType ? ` [${sanitizeCitationLookalikes(source.sourceType)}]` : ''

  return `[${index}] ${sanitizeCitationLookalikes(source.title)}${authors}${date}${venue}${kind}\n    ${renderUrl(source.url)}`
}

// Extractive fallback used when no LLM is configured or synthesis
// fails. It organizes real excerpts and never invents claims: every
// bullet quotes or points at a numbered source.
function buildExtractiveBrief(session) {
  const sources = Array.isArray(session.sources) ? session.sources : []
  const lines = []

  lines.push(`# Research Brief: ${sanitizeCitationLookalikes(session.objective)}`)
  lines.push('')
  lines.push(`Session: ${session.id} · Sources: ${sources.length} · Generated: ${new Date().toISOString().slice(0, 10)}`)
  lines.push('')

  lines.push('## Problem statement')
  lines.push('')
  lines.push(sanitizeCitationLookalikes(session.objective))
  lines.push('')

  if (session.questions && session.questions.length > 0) {
    lines.push('## Research questions')
    lines.push('')

    for (const question of session.questions) {
      lines.push(`- ${sanitizeCitationLookalikes(question)}`)
    }

    lines.push('')
  }

  lines.push('## Evidence-backed findings')
  lines.push('')

  if (sources.length === 0) {
    lines.push('No sources were retrieved. Findings are unavailable; see Limitations.')
    lines.push('')
  } else {
    for (let i = 0; i < sources.length; i += 1) {
      const source = sources[i]
      const text = (source.abstract || source.excerpt || '').trim()

      lines.push(`### [${i + 1}] ${sanitizeCitationLookalikes(source.title)}`)

      if (source.authors && source.authors.length > 0) {
        lines.push(`*${sanitizeCitationLookalikes(source.authors.slice(0, 4).join(', '))}${source.publishedAt ? ` · ${String(source.publishedAt).slice(0, 10)}` : ''}${source.venue ? ` · ${sanitizeCitationLookalikes(source.venue)}` : ''}*`)
      }

      lines.push('')
      lines.push(text ? `> ${sanitizeCitationLookalikes(text.slice(0, 1200))}` : '> No abstract or excerpt was available for this source.')
      lines.push('')
      lines.push(`Source: ${renderUrl(source.url)} · Access: ${source.accessStatus || 'unknown'}`)
      lines.push('')
    }
  }

  lines.push('## Comparison and confidence')
  lines.push('')
  lines.push('This brief was assembled extractively (no LLM synthesis). Treat each finding above as one source\'s own claim, not as an established result. Confidence is LOW until the same claim is corroborated by independent sources or reproduced locally.')
  lines.push('')

  const types = {}

  for (const source of sources) {
    const key = source.sourceType || 'unknown'
    types[key] = (types[key] || 0) + 1
  }

  if (sources.length > 0) {
    lines.push(`Source mix: ${Object.entries(types).map(([kind, count]) => `${sanitizeCitationLookalikes(kind)} x${count}`).join(', ')}.`)
    lines.push('')
  }

  lines.push('## Research gaps and recommendations')
  lines.push('')

  if (sources.length === 0) {
    lines.push('- Retry with narrower queries or check provider availability; no recommendation can be grounded without sources.')
  } else {
    lines.push('- Read the full text of the open-access sources above before committing to an approach.')
    lines.push('- Prefer claims that appear in more than one independent source; single-source claims stay tentative.')
    lines.push('- Prototype the smallest approach first and measure against a baseline from the cited work.')

    const open = sources.filter((source) => source.accessStatus === 'open').length

    lines.push(`- Open-access sources in this session: ${open} of ${sources.length}.`)
  }

  lines.push('')
  lines.push('## Implementation tasks (suggested)')
  lines.push('')
  lines.push('1. Reproduce the baseline described in the cited sources.')
  lines.push('2. Implement the smallest viable approach behind a feature flag.')
  lines.push('3. Add tests with measurable acceptance criteria from the brief.')
  lines.push('')

  lines.push('## Limitations and unresolved questions')
  lines.push('')
  lines.push('- Extractive brief: no comparative analysis was performed beyond grouping sources.')
  lines.push('- Paywalled or unreadable sources are listed with their access status and were NOT treated as read.')

  if (session.errors && session.errors.length > 0) {
    lines.push(`- Provider errors during this session: ${session.errors.length} (see session record).`)
  }

  lines.push('')
  lines.push('## Sources')
  lines.push('')

  if (sources.length === 0) {
    lines.push('(none)')
  } else {
    for (let i = 0; i < sources.length; i += 1) {
      lines.push(sourceLine(i + 1, sources[i]))
      lines.push('')
    }
  }

  return lines.join('\n').slice(0, MAX_BRIEF_CHARS)
}

function buildSynthesisPrompt(session) {
  const sources = Array.isArray(session.sources) ? session.sources : []
  const blocks = sources.slice(0, 20).map((source, index) => {
    const text = sanitizeCitationLookalikes(
      (source.abstract || source.excerpt || '(no abstract available)').slice(0, 1500)
    )
    const title = sanitizeCitationLookalikes(source.title)
    const authors = sanitizeCitationLookalikes(
      Array.isArray(source.authors) ? source.authors.join(', ') : ''
    )
    const venue = sanitizeCitationLookalikes(source.venue)

    return `[${index + 1}] ${title}\n${authors} ${source.publishedAt || ''} ${venue}\n${renderUrl(source.url)}\n${text}`
  })

  return [
    'You are synthesizing a research brief. Use ONLY the sources below.',
    'Rules: every factual claim must carry a citation like [3] that refers to the numbered source list;',
    'never cite a number outside 1-' + String(Math.max(sources.length, 1)) + ';',
    'distinguish established results from hypotheses; call out disagreements, gaps, and uncertainty;',
    'if evidence is thin, say so instead of filling gaps.',
    '',
    'Objective: ' + sanitizeCitationLookalikes(session.objective),
    'Questions: ' + sanitizeCitationLookalikes((session.questions || []).join(' | ') || '(none)'),
    '',
    'Sources:',
    ...blocks,
    '',
    'Write markdown with these sections: Problem statement, Evidence-backed findings, Comparison and confidence, Research gaps and recommendations, Implementation tasks (ordered), Test strategy and acceptance criteria, Limitations and unresolved questions, Sources (repeat the numbered list with URLs).',
  ].join('\n').slice(0, 20000)
}

// Short context block appended to AI Chat and Agent prompts so they can
// answer "what are we researching" without re-running research.
function buildResearchContext(session, maxChars = 6000) {
  const sources = Array.isArray(session.sources) ? session.sources : []
  const lines = [
    `Active research: ${sanitizeCitationLookalikes(session.objective)} (session ${session.id}, status ${session.status})`,
  ]

  if (Array.isArray(session.questions) && session.questions.length > 0) {
    lines.push(`Questions: ${sanitizeCitationLookalikes(session.questions.slice(0, 4).join(' | '))}`)
  }

  lines.push(`Sources (${sources.length}):`)

  for (let i = 0; i < Math.min(sources.length, 12); i += 1) {
    lines.push(`[${i + 1}] ${sanitizeCitationLookalikes(sources[i].title)} — ${renderUrl(sources[i].url)}`)
  }

  if (session.brief && session.brief.markdown) {
    lines.push('')
    lines.push('Brief excerpt:')
    // The brief keeps its real citations: it was sanitized at build.
    lines.push(session.brief.markdown.slice(0, Math.max(1000, maxChars - 2000)))
  } else if (Array.isArray(session.findings) && session.findings.length > 0) {
    lines.push('')
    lines.push('Findings:')

    for (const finding of session.findings.slice(0, 8)) {
      lines.push(`- ${sanitizeCitationLookalikes(finding.claim)} [${(finding.sourceIndexes || []).join(', ')}]`)
    }
  }

  if (session.decisions.length > 0) {
    lines.push('')
    lines.push(`Decisions: ${session.decisions.slice(0, 4).map((entry) => entry.text || entry).join(' | ')}`)
  }

  return lines.join('\n').slice(0, maxChars)
}

// Loads the saved session and returns the prompt-ready context
// block. Throws honestly when the session is missing so callers
// never answer from a stale or guessed brief.
async function loadResearchContext(sessionId, maxChars = 6000) {
  if (typeof sessionId !== 'string' || !sessionId.trim() || sessionId.length > 64) {
    throw new Error('Invalid research session id.')
  }

  const session = await readSession(sessionId.trim())

  return {
    sessionId: session.id,
    objective: session.objective,
    status: session.status,
    context: buildResearchContext(session, maxChars),
  }
}

module.exports = {
  validateBrief,
  buildExtractiveBrief,
  buildSynthesisPrompt,
  buildResearchContext,
  loadResearchContext,
  citationIndexes,
  sanitizeCitationLookalikes,
  MAX_BRIEF_CHARS,
}
